    Icon: MessageSquareText,
    art: { en: ['Speak', 'Review', 'Share'], te: ['మాట్లాడు', 'సమీక్ష', 'పంచుకోండి'], hi: ['बोलें', 'समीक्षा', 'साझा करें'] },
    related: ['frontend-design', 'ai-lesion-detection', 'doctor-dashboard'],
    content: {
      en: { title: 'Voice Assistant', intro: 'A language-inclusive way to record symptoms in a person’s own words.', overview: 'The voice assistant can accept spoken or typed symptom descriptions in supported languages. A transcript should be reviewed for accuracy before it is shared or used in care decisions.', features: ['Voice and text entry where supported', 'English, Telugu, and Hindi interface support', 'Reviewable transcripts with clear privacy expectations'], steps: ['Choose a language and start a voice or text entry.', 'Describe the concern in your own words; avoid recording others without consent.', 'Review and correct the transcript.', 'Share it with an authorized care worker or clinician as appropriate.'], benefits: { patients: 'A familiar way to explain a concern.', community: 'A structured symptom history to support referral.', clinicians: 'Patient-reported context for a conversation, not a diagnosis.', administrators: 'Consistent language-access workflows.' }, visual: 'Voice to reviewed note', caption: 'Illustrative voice workflow; no audio is playing or stored in this diagram.' },
      te: { title: 'వాయిస్ అసిస్టెంట్', intro: 'వ్యక్తులు తమ మాటల్లో లక్షణాలను నమోదు చేసుకునే భాషా అనుకూల మార్గం.', overview: 'వాయిస్ అసిస్టెంట్ మద్దతు ఉన్న భాషల్లో మాట్లాడిన లేదా టైప్ చేసిన లక్షణ వివరణలను స్వీకరించగలదు. సంరక్షణ నిర్ణయాలకు ఉపయోగించే ముందు ట్రాన్స్‌క్రిప్ట్ ఖచ్చితత్వాన్ని సమీక్షించాలి.', features: ['మద్దతు ఉన్న చోట వాయిస్, టెక్స్ట్ నమోదు', 'ఇంగ్లీష్, తెలుగు, హిందీ ఇంటర్‌ఫేస్ మద్దతు', 'గోప్యతపై స్పష్టమైన సూచనలతో సమీక్షించగల ట్రాన్స్‌క్రిప్ట్‌లు'], steps: ['భాష ఎంచుకుని వాయిస్ లేదా టెక్స్ట్ నమోదు ప్రారంభించండి.', 'మీ ఆందోళనను మీ మాటల్లో చెప్పండి; సమ్మతి లేకుండా ఇతరుల మాటలు రికార్డు చేయకండి.', 'ట్రాన్స్‌క్రిప్ట్‌ను సమీక్షించి సరిచేయండి.', 'అవసరమైతే అనుమతి ఉన్న ఆరోగ్య కార్యకర్త లేదా వైద్యుడితో పంచుకోండి.'], benefits: { patients: 'ఆందోళనను వివరించడానికి పరిచయమైన మార్గం.', community: 'రిఫరల్‌కు తోడ్పడే క్రమబద్ధమైన లక్షణ చరిత్ర.', clinicians: 'సంభాషణకు రోగి తెలిపిన నేపథ్యం; నిర్ధారణ కాదు.', administrators: 'భాషా ప్రవేశానికి స్థిరమైన పనివిధానాలు.' }, visual: 'వాయిస్ నుంచి సమీక్షించిన గమనిక', caption: 'ఇది వాయిస్ పనివిధాన చిత్రం; ఇందులో ఆడియో ప్లే లేదా నిల్వ చేయబడదు.' },
      hi: { title: 'वॉइस असिस्टेंट', intro: 'व्यक्ति के अपने शब्दों में लक्षण दर्ज करने का भाषा-अनुकूल तरीका।', overview: 'वॉइस असिस्टेंट समर्थित भाषाओं में बोले या टाइप किए गए लक्षण विवरण ले सकता है। देखभाल के निर्णय में उपयोग से पहले ट्रांसक्रिप्ट की सटीकता जाँचनी चाहिए।', features: ['जहाँ उपलब्ध हो, आवाज़ और टेक्स्ट दर्ज करना', 'अंग्रेज़ी, तेलुगु और हिंदी इंटरफ़ेस समर्थन', 'स्पष्ट गोपनीयता अपेक्षाओं के साथ समीक्षा योग्य ट्रांसक्रिप्ट'], steps: ['भाषा चुनकर आवाज़ या टेक्स्ट प्रविष्टि शुरू करें।', 'अपनी चिंता अपने शब्दों में बताएँ; सहमति के बिना दूसरों को रिकॉर्ड न करें।', 'ट्रांसक्रिप्ट पढ़कर सुधारें।', 'ज़रूरत के अनुसार इसे अधिकृत स्वास्थ्य कार्यकर्ता या चिकित्सक से साझा करें।'], benefits: { patients: 'अपनी चिंता बताने का परिचित तरीका।', community: 'रेफरल में मदद करने वाला व्यवस्थित लक्षण विवरण।', clinicians: 'बातचीत के लिए रोगी का संदर्भ, निदान नहीं।', administrators: 'भाषा पहुँच के लिए एकसमान कार्यप्रवाह।' }, visual: 'आवाज़ से समीक्षा किए नोट तक', caption: 'यह वॉइस कार्यप्रवाह का चित्र है; इसमें ऑडियो चल या सहेजा नहीं जा रहा।' }
    }
