      hi: { title: 'टेलीमेडिसिन और अपॉइंटमेंट', intro: 'रोगी और देखभाल टीम की सहमति से दूरस्थ परामर्श या आमने-सामने मुलाक़ात तय करें।', overview: 'अपॉइंटमेंट चिकित्सक तक पहुँच व्यवस्थित करते हैं; हर चिंता के लिए दूरस्थ मुलाक़ात उपयुक्त नहीं होती। लक्षणों के अनुसार चिकित्सक आमने-सामने जाँच या तत्काल देखभाल सुझा सकता है।', features: ['अपॉइंटमेंट अनुरोध और समय निर्धारण', 'जहाँ उपलब्ध हो दूरस्थ परामर्श समन्वय', 'फॉलो-अप याद दिलाना और मुलाक़ात स्थिति'], steps: ['रोगी या कार्यकर्ता अपॉइंटमेंट का अनुरोध करता है।', 'देखभाल टीम प्रकार और समय की पुष्टि करती है।', 'रोगी दूरस्थ मुलाक़ात में जुड़ता है या केंद्र जाता है।', 'चिकित्सक योजना और फॉलो-अप दर्ज करता है।'], benefits: { patients: 'चिकित्सक से बात तय करने का स्पष्ट रास्ता।', community: 'मुलाक़ात और फॉलो-अप समन्वय का तरीका।', clinicians: 'व्यवस्थित अपॉइंटमेंट संदर्भ और स्थिति।', administrators: 'समय निर्धारण और सेवा माँग की जानकारी।' }, visual: 'अपॉइंटमेंट यात्रा', caption: 'यह अपॉइंटमेंट प्रवाह का चित्र है; लाइव परामर्श नहीं।' }
